 let shopDriverId='DRV-1',shopActiveOrderId=null;
 const shopComboStates={sent:'Aguardando o motorista conferir',pending_difference:'Diferença para conferir',received:'Conferência concluída',cancelled:'Envio cancelado'},shopOrderStates={awaiting_payment:'Aguardando pagamento',paid:'Pagamento conferido',partially_refunded:'Devolução parcial',refunded:'Devolvido e reembolsado',expired:'Prazo encerrado',cancelled:'Cancelado'};
 function shopProfile(){return ops.drivers.find(d=>d.id===shopDriverId)||ops.drivers[0];}
 function shopPending(id){return H.pendingSummary(ops,id);}
 function shopComboLines(combo){return combo.lines.map(l=>row(esc(l.name),l.sent+' un.',combo.receivedAt?'Recebido '+l.received+' · pendente '+l.pending+(l.returned?' · devolvido '+l.returned:''):'Quantidade enviada')).join('');}
 function shop(){const d=shopProfile();shopDriverId=d.id;const view=H.inventory(ops,d.id),overview=H.summary(ops),pending=shopPending(d.id),credits=R.driverCredits(ops,d.id);return heading('LOJA NO CARRO','Um combo. Cada produto sob controle.','Prepare o combo, acompanhe a conferência e veja as vendas de cada motorista.',btn('Montar e enviar combo','shop-send','primary'))+`<div class="notice">Pix ainda não conectado. As confirmações e os valores desta página são demonstrativos. O fluxo recomendado usa a conta da RODAVOLT e uma cobrança por venda.</div><form id="shop-profile-form" class="filter-row gap">${select('driverId','Motorista para acompanhar',d.id,ops.drivers.map(d=>[d.id,d.name]))}<button type="submit" class="btn">Abrir lojinha</button></form><div class="stats">${stat('Combos do motorista',String(view.combos.length),'Envios com produtos e quantidades')}${stat('Vendas aguardando Pix',String(view.orders.filter(o=>o.status==='awaiting_payment').length),'Estoque reservado, sem entrada de dinheiro')}${stat('Crédito disponível',cash(credits.available),'Lucro já conferido, separado do caixa livre')}${stat('Vendas manuais em acerto',cash(pending.gross),'Registros anteriores ou dinheiro recebido pelo motorista')}</div><div class="grid2">${panel('Combos de '+esc(d.name),view.combos.length?view.combos.slice().reverse().map(combo=>`<article class="shop-admin-combo"><h3>${esc(combo.id)}</h3>${tag(shopComboStates[combo.status],combo.status==='received'?'green':'amber')}${shopComboLines(combo)}${combo.receiptNote?`<p class="notice gap">Motorista: ${esc(combo.receiptNote)}</p>`:''}${combo.status==='pending_difference'?btn('Resolver diferença','shop-resolve','',`data-id="${combo.id}"`):''}${combo.status==='sent'?btn('Cancelar envio','shop-cancel-combo','',`data-id="${combo.id}"`):''}</article>`).join(''):'<p class="caption">Nenhum combo enviado nesta sessão. O estoque de abertura fictício do primeiro carro foi preservado.</p>',btn('Novo combo','shop-send'))}${panel('Produtos desse motorista',table(['Produto','Recebido no carro','Reservado','Disponível'],view.products.map(p=>`<tr><td>${esc(p.name)}<small>${cash(p.price)}</small></td><td>${p.qty}</td><td>${p.reserved}</td><td><strong>${p.available}</strong></td></tr>`).join(''))+'<p class="caption gap">Disponível = recebido menos reservado em pedidos. Em trânsito ainda não pode ser vendido.</p>')}</div><div class="gap">${panel('Pedidos e pagamentos',shopAdminOrders(view.orders))}</div><details class="shop-admin-details"><summary>Estoque central e produtos em trânsito</summary>${table(['Produto','Central','No(s) carro(s)','Em trânsito / diferença','Reservado','Quarentena'],overview.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.central}</td><td>${p.kit}</td><td>${p.transit}<small>${p.disputed} com diferença relatada</small></td><td>${p.reserved}</td><td>${p.quarantined}</td></tr>`).join(''))}</details><details class="shop-admin-details"><summary>Vendas manuais e acerto do motorista</summary>${row('Vendas manuais ainda não acertadas',cash(pending.gross))}${row('Custo dos produtos',cash(pending.cost))}${row('Lucro do motorista',cash(pending.commission))}<div class="actions gap">${btn('Registrar venda manual de exemplo','shop-manual')}${btn('Conferir acerto manual','shop-settle','primary',pending.sales?'':'disabled')}</div><p class="caption">Pix conferido por pedido já registra a venda e seu crédito uma vez. O acerto abaixo é somente para vendas manuais pendentes.</p>${ops.book.sales.filter(s=>(s.driverId||'DRV-1')===d.id).length?table(['Venda','Produto','Valor','Situação'],ops.book.sales.filter(s=>(s.driverId||'DRV-1')===d.id).map(s=>`<tr><td>${s.id}</td><td>${esc(s.productName)}<small>${s.qty} un.</small></td><td>${cash(s.gross)}</td><td>${s.returnedQty?'Devolvida '+s.returnedQty+'/'+s.qty:s.settled?'Conferida':'Em acerto'}${s.settled&&!s.orderId&&(s.returnedQty||0)<s.qty?'<br>'+btn('Conferir devolução','shop-refund-manual','',`data-id="${s.id}"`):''}</td></tr>`).join('')):''}</details>${shopExceptions(d)}<details class="shop-admin-details"><summary>Como o cliente vai comprar?</summary>${shopFlowExplanation()}</details>`;}
 function shopAdminOrders(orders){return orders.length?orders.slice().reverse().map(o=>`<article class="shop-admin-order"><div class="actions"><strong>${esc(o.id)} · ${cash(o.gross)}</strong>${tag(shopOrderStates[o.status],o.status==='paid'?'green':['expired','refunded','cancelled'].includes(o.status)?'gray':'amber')}</div><p class="caption">${o.lines.map(l=>l.qty+' × '+esc(l.name)).join(' · ')}</p>${o.status==='awaiting_payment'?`<p class="caption">Reserva até ${esc(new Date(o.expiresAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}. Sem dinheiro recebido.</p>`+btn('Conferir pagamento de exemplo','shop-check-payment','primary',`data-id="${o.id}"`):['paid','partially_refunded','refunded'].includes(o.status)?row('Lucro original do motorista',cash(o.driverProfit),'Os estornos conferidos ficam no histórico, sem apagar a venda.')+`<p class="caption">Referência fictícia: ${esc(o.paymentReference)}${o.refundedAmount?' · reembolso registrado '+cash(o.refundedAmount):''}</p>`+(['paid','partially_refunded'].includes(o.status)?btn('Conferir devolução e reembolso','shop-refund','',`data-id="${o.id}"`):''):['expired','cancelled'].includes(o.status)?'<p class="caption">Reserva encerrada. Se um Pix chegou depois, confira-o separadamente: não entregue por este pedido.</p>'+btn('Conferir Pix fora do prazo','shop-late-payment','',`data-id="${o.id}"`):''}${(o.returnRequestIds||[]).length?'<p class="notice gap">O motorista pediu ajuda com esta venda.</p>':''}</article>`).join(''):'<p class="caption">Nenhum pedido criado para este motorista.</p>';}
 function shopExceptions(d){const store=H.ensure(ops),refunds=store.refunds.filter(r=>r.driverId===d.id),holds=store.latePayments.filter(r=>r.driverId===d.id),quarantine=store.quarantine.filter(r=>r.driverId===d.id);return `<details class="shop-admin-details"><summary>Devoluções, Pix fora do prazo e avarias</summary><p class="caption">Recebimento físico e dinheiro precisam ser conferidos. Lucro já usado não vira desconto automático; reverta o abatimento ou confira sua recuperação antes do reembolso.</p>${refunds.length?table(['Registro','Pedido','Reembolso','Produtos'],refunds.map(r=>`<tr><td>${esc(r.id)}<small>${esc(r.date)} · ${esc(r.reference)}</small></td><td>${esc(r.orderId)}</td><td>${cash(r.gross)}</td><td>${r.lines.map(l=>esc(l.name)+': '+l.good+' bons / '+l.damaged+' em avaliação').join('<br>')}</td></tr>`).join('')):'<p class="caption">Nenhuma devolução registrada para este motorista.</p>'}${holds.map(r=>`<article class="shop-admin-order"><strong>${esc(r.id)} · ${cash(r.amount)}</strong><p>${esc(r.orderId)} · ${r.status==='held'?'Recebido fora do prazo, reservado para devolver':'Devolução conferida'}</p>${r.status==='held'?btn('Registrar devolução do Pix','shop-refund-late','',`data-id="${r.id}"`):''}</article>`).join('')}${quarantine.length?'<h3 class="gap">Produtos em avaliação</h3>'+quarantine.map(q=>`<article class="shop-admin-order"><strong>${esc(q.name)}</strong><p>${q.remaining} aguardando avaliação · valor unitário ${cash(q.unitCost)}</p>${q.remaining?btn('Avaliar produto','shop-quarantine','',`data-id="${q.id}"`):'<p class="caption">Avaliação concluída. Histórico preservado.</p>'}</article>`).join(''):''}</details><details class="shop-admin-details"><summary>Identificação dos produtos</summary><p class="caption">Anotações do SKU atual para o piloto. Rastreabilidade de vários lotes na mesma custódia exige o módulo de compras. Preço e custo de cada pedido já criado ficam preservados.</p>${ops.book.products.map(p=>`<article class="shop-admin-order"><strong>${esc(p.name)}</strong><p class="caption">Lote: ${esc(p.batch||'Não informado')} · validade: ${esc(p.expiresOn||'Não informada')}<br>Garantia: ${esc(p.warranty||'Condições a definir com o fornecedor')}</p>${btn('Editar identificação','shop-product-meta','',`data-id="${p.id}"`)}</article>`).join('')}</details>`;}
 function shopRefundForm(order){const previous=H.ensure(ops).refunds.filter(r=>r.orderId===order.id);return `<form id="shop-refund-form"><input type="hidden" name="orderId" value="${order.id}">${order.manualSaleId?`<input type="hidden" name="manualSaleId" value="${order.manualSaleId}">`:""}<p>Informe somente o que retornou nesta conferência. Produto bom volta à central; avariado fica em avaliação. O reembolso e a retirada do lucro disponível serão registrados juntos.</p>${order.lines.map(l=>{const remaining=l.qty-previous.flatMap(r=>r.lines).filter(r=>r.productId===l.productId).reduce((sum,r)=>sum+r.qty,0);return `<fieldset class="shop-return-item"><legend>${esc(l.name)} · até ${remaining} un.</legend><div class="fields">${input('good:'+l.productId,'Bom para revenda',0,`type="number" min="0" max="${remaining}" step="1" required`)}${input('damaged:'+l.productId,'Avariado / avaliar',0,`type="number" min="0" max="${remaining}" step="1" required`)}</div></fieldset>`;}).join('')}${input('date','Data da conferência','2027-01-26','type="date" required')}${input('reference','Referência do reembolso fictício','DEV-'+order.id,'required maxlength="120"')}<label class="field gap">Motivo e conferência<textarea name="note" rows="2" maxlength="500" required></textarea></label><label class="check gap"><input name="checked" type="checkbox" required>Conferi os produtos devolvidos e o reembolso demonstrativo. Nenhum banco será acionado.</label><button type="submit" class="btn primary gap">Registrar devolução e reembolso</button></form>`;}
 function shopSendForm(defaultProduct=null,requestId=''){const request=ops.requests.find(r=>r.id===requestId),active=ops.drivers.filter(d=>d.stage==='active'&&d.vehicleId&&(!request||d.id===(request.driverId||'DRV-1')));return `<form id="shop-send-form"><input type="hidden" name="requestId" value="${esc(requestId)}">${select('driverId','Quem vai receber o combo?',active.some(d=>d.id===shopDriverId)?shopDriverId:active[0]?.id||'',active.map(d=>[d.id,d.name+' · '+d.vehicleId]))}<div class="fields gap">${ops.book.products.map(p=>input('qty:'+p.id,esc(p.name)+' · central '+p.central+' un.',defaultProduct?(p.id===defaultProduct?(request?.remainingQty??request?.qty??2):0):2,`type="number" min="0" max="${p.central}" step="1" required`)).join('')}</div><label class="field gap">Observação para o motorista<textarea name="note" rows="2" maxlength="500" placeholder="Ex.: conferir o lacre e as quantidades na entrega."></textarea></label><p class="caption">Enviar separa da central e coloca em trânsito. Só a conferência do recebimento libera os produtos no app.</p><button type="submit" class="btn primary gap" ${!active.length?'disabled':''}>Enviar combo demonstrativo</button></form>`;}
 function shopDriverCombo(combo){if(combo.status==='received'||combo.status==='cancelled')return '';return `<section class="driver-combo-card"><h2>${combo.receivedAt?'Vamos conferir a diferença':'Tem um combo para você'}</h2><p>${combo.receivedAt?'Os produtos que você confirmou já estão disponíveis. O restante aguarda a RODAVOLT.':'Confira cada produto quando receber a entrega.'}</p>${combo.lines.map(l=>row(esc(l.name),l.sent+' un.',combo.receivedAt?'Você confirmou '+l.received+' · faltam conferir '+l.pending:'Enviado pela RODAVOLT')).join('')}${combo.note?`<p class="caption">${esc(combo.note)}</p>`:''}${!combo.receivedAt?`<div class="shop-receipt-actions">${btn('Recebi tudo','shop-receive-all','primary',`data-id="${combo.id}"`)}${btn('Tem algo diferente','shop-receive-difference','',`data-id="${combo.id}"`)}</div>`:btn('Pedir ajuda com o combo','driver-support')}</section>`;}
 function driverShopFlow(){const d=driverProfile(),view=H.inventory(ops,d.id);if(d.stage!=='active')return panel('Sua lojinha ainda vai chegar','<p>A RODAVOLT vai combinar o combo depois da entrega do carro. Os produtos e as quantidades aparecerão aqui.</p><button type="button" class="btn" data-driver-page="support">Tirar uma dúvida</button>');const pending=view.orders.filter(o=>o.status==='awaiting_payment'),paid=view.orders.filter(o=>o.status==='paid'),selected=view.orders.find(o=>o.id===shopActiveOrderId),profit=R.driverCredits(ops,d.id);return (selected?shopDriverOrder(selected):pending.length?shopDriverOrder(pending.at(-1)):'')+view.combos.map(shopDriverCombo).join('')+`<p class="driver-intro">Seus produtos para vender</p><p class="caption">Toque no produto que o cliente escolheu.</p><div class="driver-products">${view.products.map(p=>{const q=p.available>0&&!p.expired?H.quote(ops,d.id,[{productId:p.id,qty:1}]):null;return `<article class="driver-product"><div><h2>${esc(p.name)}</h2><p class="driver-product-price">${cash(p.price)}</p><p class="shop-stock-available">${p.expired?'Produto separado para conferir':p.available>0?'Você tem <strong>'+p.available+'</strong> para vender':'Sem unidade disponível'}</p>${p.reserved?`<p class="caption">${p.reserved} reservada(s), esperando pagamento</p>`:''}${q?`<p class="driver-product-profit">Seu lucro: ${cash(q.driverProfit)} por unidade</p>`:''}</div>${btn(p.expired?'Aguardar conferência':p.available>0?'Vender este produto':'Aguardar reposição','shop-driver-sell','primary',`data-id="${p.id}" ${p.available<=0||p.expired?'disabled':''}`)}</article>`;}).join('')}</div><details class="driver-detail-card"><summary>Minhas vendas e meu lucro</summary>${row('Lucro disponível para desconto',cash(profit.available))}${btn('Ver meu aluguel','driver-wallet')}${view.orders.length?view.orders.slice().reverse().map(o=>`<article class="driver-request"><strong>${shopOrderStates[o.status]} · ${cash(o.gross)}</strong><p>${o.lines.map(l=>l.qty+' × '+esc(l.name)).join(', ')}</p>${o.status!=='cancelled'?btn(['paid','partially_refunded','refunded'].includes(o.status)?'Ver detalhes da venda':'Ver pedido','shop-order','',`data-id="${o.id}"`):''}</article>`).join(''):'<p>Você ainda não criou uma venda.</p>'}</details><details class="driver-detail-card"><summary>Pedir mais produtos</summary><form id="stock-request-form"><div class="fields">${select('productId','Qual produto?','perfume',ops.book.products.map(p=>[p.id,p.name]))}${input('qty','Quantas unidades?',2,'type="number" inputmode="numeric" min="1" max="999" step="1" required')}</div><button type="submit" class="btn primary gap">Pedir produtos</button></form>${driverRequests('stock')}</details>${driverSettlement()}<details class="driver-detail-card"><summary>Como funciona o pagamento?</summary>${shopFlowExplanation()}</details>`;}
 function shopDriverOrder(order,customer=false){const paid=['paid','partially_refunded'].includes(order.status),ended=['cancelled','expired','refunded'].includes(order.status),delivered=!!order.deliveredAt||!!order.manual,refunds=H.ensure(ops).refunds.filter(r=>r.orderId===order.id);return `<section data-shop-order-id="${order.id}" class="driver-payment-card ${paid?'payment-paid':''}"><div class="shop-payment-icon">${driverIcon(paid?'inspection':'wallet')}</div><h2>${order.status==='refunded'?'Compra devolvida':order.status==='partially_refunded'?'Parte da compra foi devolvida':paid?(delivered?'Venda concluída':'Pagamento conferido'):order.status==='expired'?'O prazo da compra acabou':order.status==='cancelled'?'Venda cancelada':customer?'Pagamento da compra':'Esperando pagamento'}</h2><strong class="shop-payment-value">${cash(order.gross)}</strong><p>${order.lines.map(l=>l.qty+' × '+esc(l.name)).join('<br>')}</p>${refunds.length?`<p>A equipe conferiu ${cash(order.refundedAmount)} em devolução. O lucro correspondente foi retirado do saldo disponível.</p>`:''}${paid?(customer?'<p>Pagamento conferido. Sua compra será entregue pelo motorista.</p>':`<p><strong>${delivered?'Você já entregou o produto.':order.status==='partially_refunded'?'Entregue somente os produtos que ficaram na compra.':'Pode entregar o produto.'}</strong></p><p>Confira seu lucro disponível em Meu aluguel.</p>`):ended?`<p>${order.status==='refunded'?'A devolução foi registrada pela equipe.':order.status==='expired'?'Os produtos foram liberados para outra venda. Se o cliente pagou depois, peça ajuda à equipe antes de entregar.':'Os produtos voltaram a ficar disponíveis.'}</p>`:`<div class="shop-pix-placeholder" aria-label="Área reservada para QR Pix, ainda não conectado">${driverIcon('wallet')}<strong>Pix ainda não conectado</strong><span>Aqui aparecerá o QR desta compra</span></div><p>${customer?'Na operação real, abra o app do seu banco, leia o QR Pix e confira o nome RODAVOLT e o valor antes de pagar. Não precisa de cadastro na loja.':'Na operação real, o cliente paga pelo app do banco. Você espera a confirmação por aqui.'}</p><p class="caption">Reserva de 15 minutos. Demonstração sem cobrança real. Comprovante não confirma pagamento.</p>`}${!customer?`<div class="shop-receipt-actions">${!paid&&!ended?btn('Mostrar ao cliente','shop-customer','primary',`data-id="${order.id}"`)+btn('Cancelar esta venda','shop-cancel-order','',`data-id="${order.id}"`):paid&&!delivered?btn('Entreguei o produto','shop-deliver-order','primary',`data-id="${order.id}"`):btn('Continuar vendendo','shop-order-dismiss','primary')}${paid?btn('Cliente quer devolver','shop-request-return','',`data-id="${order.id}"`):order.status==='expired'?btn('Pedir ajuda','driver-support'):''}</div>${(order.returnRequestIds||[]).map(id=>{const r=ops.requests.find(r=>r.id===id);return r?`<p class="notice gap">${r.reply?esc(r.reply):'A equipe recebeu seu pedido de ajuda. Aguarde a orientação antes de devolver dinheiro.'}</p>`:'';}).join('')}`:''}</section>`;}
 function shopFlowExplanation(){return '<ol class="shop-flow-steps"><li>Você escolhe o produto e a quantidade.</li><li>O cliente paga o Pix da venda pelo aplicativo do banco.</li><li>A confirmação aparece no app. Aí você entrega o produto.</li><li>O estoque diminui uma vez e seu lucro fica separado.</li></ol><p>Não precisa instalar outro app nem se cadastrar em uma loja. Um QR impresso para abrir o catálogo pode ser uma próxima etapa.</p><p class="caption">O banco e a confirmação automática serão conectados depois. Nesta versão, a gestão confere apenas pagamentos fictícios.</p>';}
 function shopUpdateQuote(){const form=root.querySelector('#shop-order-form');if(!form)return;const f=new FormData(form),box=form.querySelector('[data-shop-quote]');try{const q=H.quote(ops,activeDriverId,[{productId:String(f.get('productId')),qty:Number(f.get('qty'))}]);box.innerHTML=row('Cliente vai pagar',cash(q.gross),'',true)+row('Seu lucro',cash(q.driverProfit),'Disponível depois do pagamento conferido.');}catch(error){box.innerHTML=`<p class="form-error" role="alert">${esc(error.message)}</p>`;}}
 function shopAction(action,e){
  if(action==='shop-refund-manual'){if(mode!=='admin')throw new RangeError('A gestão confere a devolução manual.');const sale=ops.book.sales.find(s=>s.id===e.dataset.id);if(!sale?.settled)throw new RangeError('Confira o acerto antes da devolução.');const previous=H.ensure(ops).orders.find(o=>o.id==='MAN-'+sale.id),order={...(previous||{id:'MAN-'+sale.id,lines:[{productId:sale.productId,name:sale.productName,qty:sale.qty}]}),manualSaleId:sale.id};open('Conferir devolução da venda manual',shopRefundForm(order));return true;}
  if(action==='shop-refund'){if(mode!=='admin')throw new RangeError('A gestão confere a devolução e o dinheiro.');const order=H.ensure(ops).orders.find(o=>o.id===e.dataset.id);if(!order)throw new RangeError('Venda não encontrada.');open('Conferir devolução da compra',shopRefundForm(order));return true;}
  if(action==='shop-request-return'){open('O cliente quer devolver?',`<form id="shop-request-return-form"><input type="hidden" name="orderId" value="${e.dataset.id}"><p>Conte o que aconteceu. A RODAVOLT vai orientar você. Não devolva dinheiro nem coloque o produto à venda antes da conferência.</p><label class="field">O que aconteceu?<textarea name="note" rows="3" maxlength="500" required></textarea></label><button type="submit" class="btn primary gap">Pedir ajuda com esta compra</button></form>`);return true;}
  if(action==='shop-quarantine'){if(mode!=='admin')throw new RangeError('A gestão avalia os produtos.');const q=H.ensure(ops).quarantine.find(q=>q.id===e.dataset.id);open('Avaliar produto devolvido',`<form id="shop-quarantine-form"><input type="hidden" name="quarantineId" value="${q.id}"><p>${esc(q.name)} · ${q.remaining} aguardando conferência.</p>${input('qty','Quantidade avaliada',q.remaining,`type="number" min="1" max="${q.remaining}" step="1" required`)}${select('resolution','Resultado da avaliação','restock',[['restock','Produto íntegro · devolver à central'],['writeoff','Produto sem condição · registrar perda da empresa']])}${input('date','Data da avaliação','2027-01-27','type="date" required')}${input('reference','Referência','AVAL-'+q.id,'required maxlength="120"')}<label class="field gap">Motivo e evidência da conferência<textarea name="note" rows="2" required maxlength="500"></textarea></label><p class="caption">Uma perda reduz estoque e resultado da empresa. Não cria cobrança ao motorista.</p><button type="submit" class="btn primary gap">Registrar avaliação demonstrativa</button></form>`);return true;}
  if(action==='shop-late-payment'||action==='shop-refund-late'){if(mode!=='admin')throw new RangeError('A gestão confere recebimentos fora do prazo.');const refund=action==='shop-refund-late',record=refund?H.ensure(ops).latePayments.find(r=>r.id===e.dataset.id):H.ensure(ops).orders.find(r=>r.id===e.dataset.id);open(refund?'Conferir devolução do Pix':'Conferir Pix fora do prazo',`<form id="${refund?'shop-refund-late-form':'shop-late-payment-form'}"><input type="hidden" name="recordId" value="${record.id}"><p>${cash(refund?record.amount:record.gross)} · ${refund?'Registre somente depois de conferir a devolução fictícia.':'Esse recebimento será uma obrigação de devolver ao cliente, sem venda, lucro ou baixa de produto.'}</p>${input('date','Data da conferência','2027-01-26','type="date" required')}${input('reference','Referência da conferência',(refund?'DEV-':'TARDIO-')+record.id,'required maxlength="120"')}<label class="field gap">Motivo e conferência<textarea name="note" rows="2" maxlength="500" required></textarea></label><label class="check gap"><input name="checked" type="checkbox" required>Conferi este movimento de exemplo. Nenhum banco será acionado.</label><button type="submit" class="btn primary gap">${refund?'Registrar devolução fictícia':'Registrar recebimento fictício para devolver'}</button></form>`);return true;}
  if(action==='shop-product-meta'){if(mode!=='admin')throw new RangeError('A gestão revisa o catálogo.');const p=ops.book.products.find(p=>p.id===e.dataset.id);open('Identificação do produto',`<form id="shop-product-meta-form"><input type="hidden" name="productId" value="${p.id}"><h3>${esc(p.name)}</h3>${input('batch','Lote informado (anotação do SKU)',p.batch||'','maxlength="80"')}${input('expiresOn','Validade (se houver)',p.expiresOn||'','type="date"')}<label class="field gap">Condições de garantia / fornecedor<textarea name="warranty" rows="2" maxlength="250">${esc(p.warranty||'')}</textarea></label><p class="caption">A validade impede novas vendas de produto vencido. Pedidos criados antes preservam sua identificação.</p><button type="submit" class="btn primary gap">Salvar identificação</button></form>`);return true;}
  if(action==='shop-send'||action==='stock-transfer'){if(mode!=='admin')throw new RangeError('O envio é feito pela gestão.');open('Montar combo de produtos',shopSendForm(e.dataset.id||null));return true;}
  if(action==='shop-receive-all'||action==='shop-receive-difference'){const c=H.inventory(ops,activeDriverId).combos.find(c=>c.id===e.dataset.id);if(!c||c.receivedAt)throw new RangeError('Este combo não está disponível para conferência.');const difference=action==='shop-receive-difference';open(difference?'Conte o que veio diferente':'Confira seu combo',`<form id="shop-receive-form"><input type="hidden" name="comboId" value="${c.id}"><p>${difference?'Informe a quantidade boa que chegou de cada produto. O restante fica para a RODAVOLT conferir.':'Confira os produtos antes de confirmar. Eles ficarão disponíveis para venda.'}</p>${difference?`<div class="fields">${c.lines.map(l=>input('qty:'+l.productId,esc(l.name)+' · enviado '+l.sent,l.sent,`type="number" inputmode="numeric" min="0" max="${l.sent}" step="1" required`)).join('')}</div><label class="field gap">O que faltou ou veio com problema?<textarea name="note" rows="3" maxlength="500" required></textarea></label>`:shopComboLines(c)+c.lines.map(l=>`<input type="hidden" name="qty:${l.productId}" value="${l.sent}">`).join('')}<button type="submit" class="btn primary gap">${difference?'Enviar conferência':'Confirmar que recebi tudo'}</button></form>`);return true;}
  if(action==='shop-resolve'){const c=H.ensure(ops).combos.find(c=>c.id===e.dataset.id);open('Conferir diferença do combo',`<form id="shop-resolve-form"><input type="hidden" name="comboId" value="${c.id}">${select('productId','Produto',c.lines.find(l=>l.pending)?.productId,c.lines.filter(l=>l.pending).map(l=>[l.productId,l.name+' · pendente '+l.pending]))}${input('qty','Quantidade conferida',1,'type="number" min="1" step="1" required')}${select('resolution','O que foi conferido?','deliver',[['deliver','Restante entregue e conferido com o motorista'],['return','Produto retornou à central']])}<label class="field gap">Registro da conferência<textarea name="note" rows="3" required maxlength="500"></textarea></label><button type="submit" class="btn primary gap">Registrar conferência demonstrativa</button></form>`);return true;}
  if(action==='shop-cancel-combo'){open('Cancelar envio',`<form id="shop-cancel-combo-form"><input type="hidden" name="comboId" value="${e.dataset.id}"><p>Cancelar devolve à central os produtos do combo ainda não recebido.</p><label class="field">Motivo<textarea name="note" rows="2" required maxlength="500"></textarea></label><button type="submit" class="btn primary gap">Cancelar envio demonstrativo</button></form>`);return true;}
  if(action==='shop-driver-sell'||action==='driver-sell'){const p=H.inventory(ops,activeDriverId).products.find(p=>p.id===e.dataset.id);if(!p||p.available<1)throw new RangeError('Este produto ainda não está disponível para vender.');open('Quantas unidades?',`<form id="shop-order-form"><input type="hidden" name="productId" value="${p.id}"><h3>${esc(p.name)}</h3><p>${cash(p.price)} cada · ${p.available} disponível(is)</p>${input('qty','Quantas unidades o cliente quer?',1,`type="number" inputmode="numeric" min="1" max="${p.available}" step="1" required`)}<div data-shop-quote class="gap"></div><button type="submit" class="btn primary gap">Mostrar pagamento</button><p class="caption">O Pix desta prévia não faz cobrança real.</p></form>`);shopUpdateQuote();return true;}
  if(action==='shop-order'||action==='shop-customer'){const o=H.inventory(ops,activeDriverId).orders.find(o=>o.id===e.dataset.id);if(!o)throw new RangeError('Esta venda não está no seu app.');shopActiveOrderId=o.id;if(action==='shop-customer')open('Lojinha RODAVOLT · compra do cliente',shopDriverOrder(o,true));else{driverReceipt=null;driverPage='shop';render();}return true;}
  if(action==='shop-deliver-order'){H.deliverOrder(ops,e.dataset.id,activeDriverId);render();persist();toast('Entrega registrada. Venda concluída.');return true;}
  if(action==='shop-order-dismiss'){shopActiveOrderId=null;render();return true;}
  if(action==='shop-cancel-order'){open('Cancelar esta venda?',`<form id="shop-cancel-order-form"><input type="hidden" name="orderId" value="${e.dataset.id}"><p>Se o cliente não vai comprar, os produtos voltam a ficar disponíveis.</p><p class="caption">Se ele já pagou, aguarde a RODAVOLT conferir. Uma venda paga precisa de devolução.</p><button type="submit" class="btn primary gap">Cancelar venda sem pagamento</button><button type="button" class="btn gap" data-action="close">Voltar</button></form>`);return true;}
  if(action==='shop-check-payment'){if(mode!=='admin')throw new RangeError('Só a gestão confere o pagamento no teste.');const o=H.ensure(ops).orders.find(o=>o.id===e.dataset.id);open('Conferir pagamento fictício',`<form id="shop-payment-form"><input type="hidden" name="orderId" value="${o.id}">${row('Pedido',esc(o.id))}${row('Motorista',esc(M.driver(ops,o.driverId).name))}${row('Valor a conferir',cash(o.gross))}${input('reference','Referência do recebimento fictício','DEMO-'+o.id,'required maxlength="120"')}<label class="check gap"><input type="checkbox" name="checked" required>Conferi este recebimento de exemplo. Não é comprovante enviado pelo cliente.</label><p class="notice">A confirmação registra este pedido e o lucro do motorista uma única vez. Nenhum banco será acionado.</p><button type="submit" class="btn primary gap">Confirmar pagamento de exemplo</button></form>`);return true;}
  if(action==='shop-manual'){open('Venda manual demonstrativa',`<form id="shop-manual-form">${select('driverId','Motorista',shopDriverId,ops.drivers.filter(d=>d.stage==='active').map(d=>[d.id,d.name]))}${select('productId','Produto','perfume',ops.book.products.map(p=>[p.id,p.name]))}${input('qty','Quantidade',1,'type="number" min="1" step="1" required')}${select('method','Quem recebeu?','driver',[['driver','Motorista recebeu em dinheiro'],['company','Empresa recebeu · conferência manual']])}<button type="submit" class="btn primary gap">Registrar venda em acerto</button></form>`);return true;}
  if(action==='shop-settle'){open('Acerto manual do motorista',`<form id="shop-settle-form"><input type="hidden" name="driverId" value="${shopDriverId}">${select('reward','Destino do lucro','credit',[['credit','Bruto conferido na empresa · gerar crédito'],['payout','Lucro já recebido em dinheiro pelo motorista']])}<label class="check"><input type="checkbox" name="checked" required>Conferi os valores e o destino do lucro de todas as vendas manuais pendentes deste motorista.</label><button type="submit" class="btn primary gap">Confirmar acerto de exemplo</button></form>`);return true;}
  if(action==='resolve-request'){const r=ops.requests.find(r=>r.id===e.dataset.id);if(r?.type==='stock'){shopDriverId=r.driverId||'DRV-1';open('Preparar combo para reposição',shopSendForm(r.productId,r.id));return true;}}
  return false;
 }
 function shopSubmit(form,f){const n=k=>Number(f.get(k)),lines=()=>ops.book.products.map(p=>({productId:p.id,qty:n('qty:'+p.id)})).filter(l=>l.qty>0);let message='Registro salvo na demonstração.';
  const adminForms=['shop-refund-form','shop-quarantine-form','shop-late-payment-form','shop-refund-late-form','shop-product-meta-form'];if(adminForms.includes(form.id)&&mode!=='admin')throw new RangeError('Este registro é feito pela gestão.');
  const checkInput=()=>({confirmedBy:'management',reference:String(f.get('reference')||''),note:String(f.get('note')||''),date:String(f.get('date')||'')});
  if(form.id==='shop-refund-form'){if(!f.has('checked'))throw new RangeError('Confira o retorno dos produtos e o reembolso de exemplo.');const manualSaleId=String(f.get('manualSaleId')||''),sale=manualSaleId?ops.book.sales.find(s=>s.id===manualSaleId):null,order=H.ensure(ops).orders.find(o=>o.id===f.get('orderId'))||(sale?{id:'MAN-'+sale.id,lines:[{productId:sale.productId}]}:null);H[manualSaleId?'refundManualSale':'refundOrder'](ops,manualSaleId||order.id,{...checkInput(),lines:order.lines.map(l=>({productId:l.productId,good:n('good:'+l.productId),damaged:n('damaged:'+l.productId)})).filter(l=>l.good+l.damaged>0)});message='Devolução registrada. Estoque, dinheiro e lucro ajustados uma vez.';}
  else if(form.id==='shop-request-return-form'){H.requestReturn(ops,String(f.get('orderId')),activeDriverId,{note:String(f.get('note')||'')});message='A equipe recebeu seu pedido de ajuda com a compra.';}
  else if(form.id==='shop-quarantine-form'){H.evaluateQuarantine(ops,String(f.get('quarantineId')),{...checkInput(),qty:n('qty'),action:String(f.get('resolution'))});message='Avaliação registrada. Nenhuma cobrança criada para o motorista.';}
  else if(form.id==='shop-late-payment-form'||form.id==='shop-refund-late-form'){if(!f.has('checked'))throw new RangeError('Confira o movimento de exemplo.');H[form.id==='shop-late-payment-form'?'recordLatePayment':'refundLatePayment'](ops,String(f.get('recordId')),checkInput());message='Movimento fora do prazo conferido, sem criar venda.';}
  else if(form.id==='shop-product-meta-form'){H.updateProduct(ops,String(f.get('productId')),{batch:String(f.get('batch')||''),expiresOn:String(f.get('expiresOn')||''),warranty:String(f.get('warranty')||'')});message='Identificação atualizada. Pedidos anteriores preservados.';}
  else if(form.id==='shop-profile-form'){shopDriverId=String(f.get('driverId'));}
  else if(form.id==='shop-send-form'){const d=M.driver(ops,String(f.get('driverId')));H.sendCombo(ops,{driverId:d.id,vehicleId:d.vehicleId,lines:lines(),note:String(f.get('note')),requestId:String(f.get('requestId')||'')});shopDriverId=d.id;message='Combo enviado. Aguardando o motorista conferir.';}
  else if(form.id==='shop-receive-form'){const c=H.inventory(ops,activeDriverId).combos.find(c=>c.id===f.get('comboId'));if(!c)throw new RangeError('Combo não encontrado para você.');H.receiveCombo(ops,c.id,activeDriverId,{lines:c.lines.map(l=>({productId:l.productId,qty:n('qty:'+l.productId)})),note:String(f.get('note')||'')});driverDone('Combo conferido','Os produtos que você confirmou já aparecem disponíveis para vender.','shop','Ver meus produtos');return true;}
  else if(form.id==='shop-resolve-form'){if(mode!=='admin')throw new RangeError('A gestão confere esta diferença.');H.resolveDifference(ops,String(f.get('comboId')),{productId:String(f.get('productId')),qty:n('qty'),action:String(f.get('resolution')),note:String(f.get('note'))});}
  else if(form.id==='shop-cancel-combo-form'){if(mode!=='admin')throw new RangeError('A gestão cancela o envio.');H.cancelCombo(ops,String(f.get('comboId')),{note:String(f.get('note'))});}
  else if(form.id==='shop-order-form'){const o=H.createOrder(ops,{driverId:activeDriverId,vehicleId:driverVehicle()?.id,lines:[{productId:String(f.get('productId')),qty:n('qty')}]});shopActiveOrderId=o.id;driverReceipt=null;}
  else if(form.id==='shop-cancel-order-form'){H.cancelOrder(ops,String(f.get('orderId')),activeDriverId);shopActiveOrderId=null;message='Venda cancelada. Os produtos voltaram a ficar disponíveis.';}
  else if(form.id==='shop-payment-form'){if(mode!=='admin'||!f.has('checked'))throw new RangeError('A gestão precisa conferir o recebimento de exemplo.');H.confirmPayment(ops,String(f.get('orderId')),{confirmedBy:'management',reference:String(f.get('reference'))});message='Pagamento fictício conferido. Estoque e crédito do motorista atualizados uma vez.';}
  else if(form.id==='shop-manual-form'){const d=M.driver(ops,String(f.get('driverId')));H.recordSale(ops,{driverId:d.id,vehicleId:d.vehicleId,productId:String(f.get('productId')),qty:n('qty'),method:String(f.get('method'))});shopDriverId=d.id;}
  else if(form.id==='shop-settle-form'){if(!f.has('checked'))throw new RangeError('Confira os valores e o destino do lucro.');R.settle(ops,String(f.get('reward')),String(f.get('driverId')));}
  else return false;
  close();render();persist();toast(message);if(mode==='driver'){window.scrollTo({top:0,behavior:'instant'});main.querySelector('[data-driver-title]')?.focus({preventScroll:true});}return true;
 }

 // Keep a waiting customer's screen honest while the page remains open.
 function shopCheckExpirations(){const expired=H.expireOrders(ops);if(!expired.length)return;persist();if(dialog.open){const card=dialog.querySelector('[data-shop-order-id]');if(card&&expired.includes(card.dataset.shopOrderId)){const order=H.ensure(ops).orders.find(o=>o.id===card.dataset.shopOrderId);root.querySelector('#detail-content').innerHTML=shopDriverOrder(order,true);}}else if(mode==='admin'&&page==='shop'||mode==='driver'&&driverPage==='shop'){render();toast('O prazo de uma compra acabou. Os produtos foram liberados para vender.');}}
 setInterval(shopCheckExpirations,15000);
